#!/usr/bin/env python3
"""Auto-recovery module for LMR Phase 1 tuning campaign.

Restores full Iteration 1-80 history (12,000 games) and checkpoint state when
running on a freshly initialized Google Colab instance.
"""

import json
import gzip
import base64
from pathlib import Path

# Base64-encoded gzipped jsonl logs for all 80 iterations
LOG_GZ_B64 = ""

STATE_TEMPLATE = {
  "iteration": 80,
  "theta": {
    "LMR_BASE_OFFSET": 434.9316015778605,
    "LMR_HISTORY_SCALE": 204.0733094460964,
    "LMR_CUTNODE_BONUS": 1838.7703602698164,
    "LMR_TTCAPTURE_BONUS": 1179.9756911019763,
    "LMR_MOVECOUNT_FACTOR": 34.86271688907439,
    "LMR_TABLE_SCALE_PERCENT": 113.0156875541869
  },
  "current_params": {
    "LMR_BASE_OFFSET": 457,
    "LMR_HISTORY_SCALE": 186,
    "LMR_CUTNODE_BONUS": 1920,
    "LMR_TTCAPTURE_BONUS": 1155,
    "LMR_MOVECOUNT_FACTOR": 37,
    "LMR_TABLE_SCALE_PERCENT": 109
  },
  "backend": "inprocess",
  "profile": "runtime",
  "params": [
    "LMR_BASE_OFFSET",
    "LMR_HISTORY_SCALE",
    "LMR_CUTNODE_BONUS",
    "LMR_TTCAPTURE_BONUS",
    "LMR_MOVECOUNT_FACTOR",
    "LMR_TABLE_SCALE_PERCENT"
  ],
  "games": 150,
  "nodes": 50000,
  "concurrency": 7,
  "log": "tune_search/logs/lmr_p1_deep_l1.jsonl",
  "match_games": 150,
  "spsa_update_mode": "classic_fishtest_v5",
  "spsa_schedule": "fishtest_classic",
  "spsa_iteration": 6000,
  "schedule_total_batches": 80,
  "match_pairs": 75,
  "total_pairs": 6000,
  "A_ratio": 0.1,
  "A": 600.0,
  "alpha": 0.602,
  "gamma": 0.101,
  "scale_mode": "integer",
  "theta_plus": {
    "LMR_BASE_OFFSET": 435,
    "LMR_HISTORY_SCALE": 204,
    "LMR_CUTNODE_BONUS": 1839,
    "LMR_TTCAPTURE_BONUS": 1180,
    "LMR_MOVECOUNT_FACTOR": 35,
    "LMR_TABLE_SCALE_PERCENT": 113
  },
  "theta_minus": {
    "LMR_BASE_OFFSET": 435,
    "LMR_HISTORY_SCALE": 204,
    "LMR_CUTNODE_BONUS": 1839,
    "LMR_TTCAPTURE_BONUS": 1180,
    "LMR_MOVECOUNT_FACTOR": 35,
    "LMR_TABLE_SCALE_PERCENT": 113
  }
}

def restore_checkpoint(concurrency: int = 7, force: bool = False):
    """Restore state file and jsonl log for LMR Phase 1 tuning."""
    state_path = Path("tune_search/states/lmr_p1_deep_l1.json")
    log_path = Path("tune_search/logs/lmr_p1_deep_l1.jsonl")
    curr_params_path = Path("tune_search/current_params.txt")

    if state_path.exists() and not force:
        print(f"[recover] Existing checkpoint detected at {state_path}, skipping recovery.")
        return

    print("[recover] Restoring full Iter 1-80 history (12,000 games)...")
    state_path.parent.mkdir(parents=True, exist_ok=True)
    log_path.parent.mkdir(parents=True, exist_ok=True)

    state = dict(STATE_TEMPLATE)
    state["concurrency"] = int(concurrency)

    with state_path.open("w", encoding="utf-8") as f:
        json.dump(state, f, indent=2, ensure_ascii=False)

    log_data = gzip.decompress(base64.b64decode(LOG_GZ_B64))
    with log_path.open("wb") as f:
        f.write(log_data)

    current_params = state.get("current_params", {})
    with curr_params_path.open("w", encoding="utf-8") as f:
        f.write(str(current_params))

    print(f"[recover] Successfully restored all 80 iterations to {log_path}.")
    print(f"[recover] Successfully created checkpoint at {state_path} (iteration={state['iteration']}, concurrency={concurrency}).")

if __name__ == "__main__":
    restore_checkpoint()
